using System.Text.Json.Serialization;
namespace CollageDesigner;
public sealed class LayoutSlot { public double X {get;set;} public double Y {get;set;} public double Width {get;set;} public double Height {get;set;} }
public sealed class LayoutTemplate { public string Id {get;set;}=""; public string Name {get;set;}=""; public int PhotoCount {get;set;} public List<LayoutSlot> Slots {get;set;}=[]; }
public sealed class PhotoTransform { public double Scale {get;set;}=1; public double PanX {get;set;} public double PanY {get;set;} }
public sealed class PhotoEntry { public string Path {get;set;}=""; public PhotoTransform Transform {get;set;}=new(); [JsonIgnore] public int Width {get;set;} [JsonIgnore] public int Height {get;set;} [JsonIgnore] public byte[]? Preview {get;set;} }
public sealed class ProjectData { public List<PhotoEntry> Photos {get;set;}=[]; public List<int> Assignments {get;set;}=[]; public Dictionary<string,List<LayoutSlot>> CustomLayouts {get;set;}=[]; public List<int> LayerOrder {get;set;}=[]; public bool MoveUsedPhotosAfterExport {get;set;} public string Unit {get;set;}="Pixels"; public double Width {get;set;}=2160; public double Height {get;set;}=2700; public int Dpi {get;set;}=300; public string LayoutCollection {get;set;}="Normal"; public int LayoutIndex {get;set;} public int Gap {get;set;}=3; public int Margin {get;set;} public string Background {get;set;}="#FFFFFFFF"; public int JpegQuality {get;set;}=95; [JsonIgnore] public int PreviewFrontSlot {get;set;}=-1; [JsonIgnore] public List<int> PreviewFrontSlots {get;set;}=[]; [JsonIgnore] public int PixelWidth => Unit=="Inches" ? (int)Math.Round(Width*Dpi) : (int)Math.Round(Width); [JsonIgnore] public int PixelHeight => Unit=="Inches" ? (int)Math.Round(Height*Dpi) : (int)Math.Round(Height); }
